@startuml

class Museum {
  + name : string
}

class Location {
  + description : string
  + floor : int
}

class Exhibition {
  + title : string
  + openingDate : date
  + status : string
}

class Employee {
  + employeeID : int
  + name : string
}

class ExhibitionItem {
  + description : string
}

class Piece {
  + title : string
  + artist : string
  + year : int
}

class Collector {
  + name : string
  + contactInfo : string
}

class Request {
  + requestDate : date
  + status : string
}

Museum "1" *-- "1..*" Location
Location "1" -- "0..*" Exhibition
Exhibition "1" -- "1" Employee : coordinatedBy
Exhibition "1" *-- "1..*" ExhibitionItem
ExhibitionItem "1" -- "1..*" Request
Request "1" -- "1" Piece
Request "1" -- "1" Collector
Employee "1" -- "0..1" Employee : coachedBy
Employee "1" -- "0..*" Employee : coaches

@enduml

